sys.stdin = StringIO(test_input)

for tc in range(1, 11):
    n = int(input())
    arr = [list(map(int, input().split())) for _ in range(n)]

    count = 0

    for j in range(n):
        found_one = False

        for i in range(n):
            if arr[i][j] == 1:
                found_one = True
            elif arr[i][j] == 2 and found_one:
                count += 1
                found_one = False

    print(f'#{tc} {count}')